package com.boatyguide;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BoatyGuidePluginTest
{
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BoatyGuidePlugin.class);
		RuneLite.main(args);
	}
}

package com.boatyguide;

import com.boatyguide.guide.GuideData;
import com.boatyguide.guide.GuideDataLoader;
import com.google.gson.GsonBuilder;
import org.junit.Assert;
import org.junit.Test;

public class GuideDataLoaderTest
{
	@Test
	public void loadsGeneratedGuideData() throws Exception
	{
		GuideDataLoader loader = new GuideDataLoader(new GsonBuilder().create());
		GuideData data = loader.load();

		Assert.assertNotNull(data);
		Assert.assertEquals("3.0", data.getVersion());
		Assert.assertTrue(data.getTotalSteps() > 1000);
		Assert.assertFalse(data.getEpisodes().isEmpty());
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.anyMatch(bank -> bank.getWithdrawStepText() != null && !bank.getWithdrawStepText().isBlank()));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.anyMatch(bank -> bank.getExitStepText() != null && !bank.getExitStepText().isBlank()));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> !step.getSubsteps().isEmpty()));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> !step.getAdviceLines().isEmpty()));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getText().equals("Complete Tourist Trap")
				&& step.getAdviceLines().stream().anyMatch(line -> line.contains("Mercenary Captain"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getRawText().startsWith("Kill a Chicken.")
				&& step.getAdviceLines().stream().anyMatch(line -> line.contains("feather"))
				&& !step.getText().contains("Make sure you get a feather")));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e11_b199_s1")
				&& step.getText().contains("Talk to Demon Butler")
				&& step.getAdviceLines().isEmpty()));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e2_b36_s12")
				&& !step.getText().contains("Withdraw Air staff")
				&& step.getAdviceLines().stream().anyMatch(line -> line.startsWith("Withdraw Air staff"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e2_b33_s2")
				&& step.getText().equals("Complete Murder Mystery")
				&& step.getSubsteps().stream().anyMatch(line -> line.contains("Barcrawl"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e2_b28_s8")
				&& step.getSubsteps().stream().anyMatch(line -> line.contains("Balls of Wool"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e3_b105_s7")
				&& step.getText().equals("Find your tunnel")
				&& step.getAdviceLines().stream().anyMatch(line -> line.startsWith("Enter a Melee brother Mound"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e1_b11_s7")
				&& step.getText().equals("Use the Edgeville and Ardougne wilderness lever 4 times.")
				&& step.getAdviceLines().stream().anyMatch(line -> line.contains("Wilderness and Ardougne Diary"))));
		Assert.assertTrue(data.getEpisodes().stream()
			.flatMap(episode -> episode.getBanks().stream())
			.flatMap(bank -> bank.getSteps().stream())
			.anyMatch(step -> step.getGlobalId().equals("e3_b99_s12")
				&& step.getText().equals("Get 10 signatures for Ghost's Ahoy.")
				&& step.getAdviceLines().stream().anyMatch(line -> line.contains("Ectotokens"))));
		Assert.assertTrue(data.findStep(data.getOrderedSteps().get(0).getGlobalId()).isPresent());
	}
}

package com.boatyguide;

import com.boatyguide.guide.GuideData;
import com.boatyguide.guide.GuideDataLoader;
import com.boatyguide.guide.GuideStep;
import com.google.gson.GsonBuilder;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class GuideStateManagerTest
{
	@Test
	public void preservesProgressAcrossReload() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		String firstStep = manager.getCurrentStep().getGlobalId();
		manager.next();
		String secondStep = manager.getCurrentStep().getGlobalId();

		GuideStateManager reloaded = new GuideStateManager(store);
		reloaded.load(data);

		Assert.assertNotEquals(firstStep, secondStep);
		Assert.assertEquals(secondStep, reloaded.getCurrentStep().getGlobalId());
		Assert.assertTrue(reloaded.getCompletedStepIds().contains(firstStep));
	}

	@Test
	public void togglesCurrentBankCompletionAndAdvances() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		List<GuideStep> firstBankSteps = manager.getCurrentBank().orElseThrow().getSteps();
		String nextBankId = manager.getNextBank().orElseThrow().getBankId();

		manager.toggleCurrentBankCompleted(true);

		Assert.assertTrue(firstBankSteps.stream().allMatch(manager::isCompleted));
		Assert.assertEquals(nextBankId, manager.getCurrentStep().getBankId());

		manager.jumpToBank(firstBankSteps.get(0).getBankId());
		manager.toggleCurrentBankCompleted(false);

		Assert.assertTrue(firstBankSteps.stream().noneMatch(manager::isCompleted));
	}

	@Test
	public void setsProgressToConfiguredBank() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);

		Assert.assertTrue(manager.setProgressToBank("75"));
		Assert.assertEquals("75", manager.getCurrentStep().getBankId());
		Assert.assertTrue(data.getOrderedBanks().stream()
			.takeWhile(bank -> !bank.getBankId().equals("75"))
			.flatMap(bank -> bank.getSteps().stream())
			.allMatch(manager::isCompleted));
	}

	@Test
	public void nextCompletesAndPreviousUncompletes() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		String firstStepId = manager.getCurrentStep().getGlobalId();
		String secondStepId = data.getOrderedSteps().get(1).getGlobalId();

		manager.next();

		Assert.assertTrue(manager.getCompletedStepIds().contains(firstStepId));
		Assert.assertEquals(secondStepId, manager.getCurrentStep().getGlobalId());

		manager.previous();

		Assert.assertEquals(firstStepId, manager.getCurrentStep().getGlobalId());
		Assert.assertFalse(manager.getCompletedStepIds().contains(firstStepId));
	}

	@Test
	public void skipsWithdrawStepsInNavigation() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		manager.jumpToStep("e1_b0_s9");

		manager.next();

		Assert.assertEquals("e1_b1_s1", manager.getCurrentStep().getGlobalId());
		Assert.assertNotEquals("WITHDRAW", manager.getCurrentStep().getStepType().name());
	}

	@Test
	public void resolvesWithdrawDetailsSeparatelyFromAdvice() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		manager.jumpToStep("e2_b36_s12");

		List<String> withdrawLines = manager.getCurrentWithdrawLines();
		List<String> adviceLines = manager.getCurrentAdviceLines();

		Assert.assertTrue(withdrawLines.stream().anyMatch(line -> line.startsWith("Withdraw: Coins, Pestle & Mortar")));
		Assert.assertTrue(withdrawLines.stream().anyMatch(line -> line.startsWith("Withdraw Air staff")));
		Assert.assertFalse(adviceLines.stream().anyMatch(line -> line.startsWith("Withdraw Air staff")));
	}

	@Test
	public void allowsHandoffWhenOnlyTrailingBankAdviceRemains() throws Exception
	{
		GuideData data = loadGuideData();
		InMemoryProgressStore store = new InMemoryProgressStore();
		GuideStateManager manager = new GuideStateManager(store);

		manager.load(data);
		manager.jumpToStep("e1_b0_s9");

		Assert.assertTrue(manager.isDepositHandoffStep());
		Assert.assertTrue(manager.getCurrentWithdrawLines().stream()
			.anyMatch(line -> line.startsWith("Withdraw: Coins, Air Runes, Mind Runes")));
	}

	private static GuideData loadGuideData() throws Exception
	{
		return new GuideDataLoader(new GsonBuilder().create()).load();
	}

	private static class InMemoryProgressStore implements GuideProgressStore
	{
		private String currentStep;
		private Set<String> completed = new LinkedHashSet<>();

		@Override
		public GuideProgressSnapshot load(String guideVersion)
		{
			return new GuideProgressSnapshot(currentStep, new LinkedHashSet<>(completed));
		}

		@Override
		public void save(String guideVersion, GuideProgressSnapshot snapshot)
		{
			currentStep = snapshot.getCurrentStepId();
			completed = new LinkedHashSet<>(snapshot.getCompletedStepIds());
		}

		@Override
		public void reset(String guideVersion)
		{
			currentStep = null;
			completed.clear();
		}
	}
}

package com.boatyguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;

@Singleton
@SuppressWarnings("deprecation")
public class WithdrawOverlay extends OverlayPanel
{
	private static final Color LABEL = new Color(255, 191, 92);
	private static final Color VALUE = Color.WHITE;

	private final GuideStateManager guideStateManager;
	private final BoatyGuideConfig config;

	@Inject
	public WithdrawOverlay(GuideStateManager guideStateManager, BoatyGuideConfig config)
	{
		this.guideStateManager = guideStateManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		if (!config.showOverlay() || !guideStateManager.isDepositHandoffStep())
		{
			return null;
		}

		List<String> withdrawLines = guideStateManager.getCurrentWithdrawLines();
		if (withdrawLines.isEmpty())
		{
			return null;
		}

		panelComponent.setBackgroundColor(new Color(30, 30, 30, 190));
		panelComponent.setPreferredSize(new Dimension(260, 0));
		addWrappedLine("Withdraw", withdrawLines.get(0));
		for (int i = 1; i < withdrawLines.size(); i++)
		{
			addWrappedLine("", withdrawLines.get(i));
		}
		return super.render(graphics);
	}

	private void addWrappedLine(String label, String text)
	{
		List<String> chunks = wrapText(text, 34);
		for (int i = 0; i < chunks.size(); i++)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(i == 0 ? label : "")
				.right(chunks.get(i))
				.leftColor(LABEL)
				.rightColor(VALUE)
				.build());
		}
	}

	private static List<String> wrapText(String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		String[] words = text.trim().split("\\s+");
		StringBuilder current = new StringBuilder();
		for (String word : words)
		{
			if (current.length() == 0)
			{
				current.append(word);
				continue;
			}

			if (current.length() + 1 + word.length() <= maxWidth)
			{
				current.append(' ').append(word);
			}
			else
			{
				lines.add(current.toString());
				current = new StringBuilder(word);
			}
		}

		if (current.length() > 0)
		{
			lines.add(current.toString());
		}

		return lines;
	}
}

package com.boatyguide;

import java.awt.event.MouseEvent;

public enum BoatyMouseBind
{
	NONE("Not set", 0),
	MIDDLE("Middle click", MouseEvent.BUTTON2),
	BACK("Mouse button 4", 4),
	FORWARD("Mouse button 5", 5);

	private final String label;
	private final int button;

	BoatyMouseBind(String label, int button)
	{
		this.label = label;
		this.button = button;
	}

	public boolean matches(MouseEvent event)
	{
		return button != 0 && event.getButton() == button;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

